@T.macro
def softplus(x: T.Ref):
    threshold = 20.0
    return T.if_then_else(x > threshold, x, T.log1p(T.exp(x)))

import torch

from tile_kernels.mhc.sinkhorn_kernel import _mhc_sinkhorn_bwd, _mhc_sinkhorn_fwd


class _SinkhornNormalize(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx: '_SinkhornNormalize',
        x: torch.Tensor,
        repeat: int,
        eps: float,
    ) -> torch.Tensor:
        hidden_size = x.shape[1]
        output = torch.empty_like(x)
        fwd_kernel = _mhc_sinkhorn_fwd(hidden_size, 1, repeat, eps)
        bwd_kernel = _mhc_sinkhorn_bwd(hidden_size, 32, repeat, eps)
        ctx.save_for_backward(x)
        ctx.bwd_kernel = bwd_kernel
        fwd_kernel(x, output)
        return output

    @staticmethod
    def backward(ctx: '_SinkhornNormalize', grad_output: torch.Tensor) -> tuple[torch.Tensor, None, None]:
        x = ctx.saved_tensors[0]
        grad_input = torch.empty_like(x)
        ctx.bwd_kernel(grad_output, x, grad_input)
        return grad_input, None, None


def sinkhorn_normalize(x: torch.Tensor, repeat: int = 10, eps: float = 1e-6) -> torch.Tensor:
    return _SinkhornNormalize.apply(x.contiguous().view(-1, *x.shape[-2:]), repeat, eps).view_as(x)

import tilelang
import torch
from tilelang import language as T

_PASS_CONFIGS = {
    tilelang.PassConfigKey.TL_DISABLE_WARP_SPECIALIZED: True,
}


@tilelang.jit(pass_configs=_PASS_CONFIGS)
def _mhc_head_compute_mix_fwd(
    mhc_mult: int,
    mhc_pre_eps: float,
    token_block_size: int,
) -> tilelang.JITKernel:
    num_tokens = T.dynamic('num_tokens')

    @T.prim_func
    def mhc_head_compute_mix_fwd_kernel(
        # Input
        input_mix: T.Tensor[(num_tokens, mhc_mult), T.float32],
        mhc_scale: T.Tensor[(1,), T.float32],
        mhc_base: T.Tensor[(mhc_mult,), T.float32],
        # Output
        output_mix: T.Tensor[(num_tokens, mhc_mult), T.float32],
    ) -> None:
        with T.Kernel(T.ceildiv(num_tokens, token_block_size)) as pid:
            for i1, j in T.Parallel(token_block_size, mhc_mult):
                i = pid * token_block_size + i1
                if i < num_tokens:
                    output_mix[i, j] = T.sigmoid(input_mix[i, j] * mhc_scale[0] + mhc_base[j]) + mhc_pre_eps

    return mhc_head_compute_mix_fwd_kernel


@tilelang.jit(pass_configs=_PASS_CONFIGS)
def _mhc_head_compute_mix_bwd(
    mhc_mult: int,
    token_block_size: int,
    num_sms: int,
) -> tilelang.JITKernel:
    num_tokens = T.dynamic('num_tokens')

    @T.prim_func
    def mhc_head_compute_mix_bwd_kernel(
        # Gradient of output
        output_mix_grad: T.Tensor[(num_tokens, mhc_mult), T.float32],
        # Cached activation
